public class MyHttpMock implements HttpCalloutMock {
  public HTTPResponse respond(HTTPRequest request) {
    HTTPResponse response = new HTTPResponse();
    response.setStatusCode(200);
    response.setBody('{}');
    return response;
  }
}

public class HttpClient {
  public String fetch(String endpoint) {
    HttpRequest request = new HttpRequest();
    request.setEndpoint(endpoint);
    request.setMethod('GET');
    Http http = new Http();
    HttpResponse response = http.send(request);
    return response.getBody();
  }
}

@isTest private class HttpClientTest {
  @isTest static void fetchesSuccessfully() {
    Test.setMock(HttpCalloutMock.class, new MyHttpMock());
    HttpClient client = new HttpClient();
    String body = client.fetch('http://example.com/api');
    System.assertEquals('{}', body);
  }
}
